def priority(task, state, k=0.5, m=2.0, a=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    age = 1.0 + a * wait / max(task.estimated_runtime, 1e-6)
    return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6))) * age  # tuned (k=0.314,m=2.63,a=0.429)

def priority(task, state, c=1.0, k=0.5, m=2.0, q=1.0, s=0.5):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    queue_pressure = state.queue_len * state.mean_est / max(state.capacity, 1e-6)
    if queue_pressure > q:
        score = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    else:
        score = tier * task.weight / est * (1.0 + s * ratio)
    guard = 1e6 if ratio >= c else 0.0
    return guard + score + 1.0 / est  # tuned (c=2.09,k=0.357,m=1.14,q=1.73,s=0.447)
